new_pattern.code:
@Component
public class MyRoute extends RouteBuilder {
    @Override
    public void configure() {
        from("direct:start")
            .process(exchange -> {
                var message = exchange.getMessage();
                String body = message.getBody(String.class);
                message.setBody(body.toUpperCase());
            });
    }
}

